package io.github.phiscript.capture;import io.github.phiscript.SessionSettings;import io.github.phiscript.input.TouchService;import java.util.concurrent.atomic.AtomicBoolean;public class PhigrosAutoEngine {public static int calls;public static class ServiceChanged extends IllegalStateException {}public static String failure="";public PhigrosAutoEngine(TouchService t,FrameStore f,SessionSettings s,boolean p,AtomicBoolean stop,RecognitionOverlay o){if(failure.equals("constructor"))throw new IllegalStateException("没有谱库");}public void run()throws Exception {calls++;if(failure.equals("reconnect")&&calls==1){TouchService.current=new TouchService();throw new ServiceChanged();}if(failure.equals("exception"))throw new IllegalStateException("未能确认菜单");if(failure.equals("interrupt"))throw new InterruptedException();if(failure.equals("linkage"))throw new NoSuchMethodError("设备缺少接口");}}
